<?php
require 'includes/functions.php';$u=auth();$id=(int)($_GET['id']??0);$kind=is_string($_GET['kind']??null)?$_GET['kind']:'summary';
$order=q('SELECT * FROM orders WHERE id=?',[$id])->fetch();if(!$order||($u['role']!=='admin'&&(int)$order['user_id']!==(int)$u['id'])){http_response_code(404);exit('ไม่พบเอกสาร');}
$document=null;$buyer=[];
if($kind!=='summary'){$document=q('SELECT * FROM order_documents WHERE order_id=? AND kind=?',[$id,$kind])->fetch();if(!$document){http_response_code(404);exit('ยังไม่มีเอกสารที่ออกแล้ว');}$snapshot=json_decode($document['snapshot'],true);$order=$snapshot['order'];$items=$snapshot['items'];$tax=$snapshot['tax'];$buyer=$snapshot['buyer'];}
else{$items=q('SELECT * FROM order_items WHERE order_id=? ORDER BY id',[$id])->fetchAll();$tax=json_decode($order['tax_snapshot']??'{}',true)?:[];}
header('Cache-Control: private, no-store');$title=$kind==='tax_invoice'?'ใบกำกับภาษี':($kind==='receipt'?'ใบเสร็จรับเงิน':'สรุปคำสั่งซื้อ');
?><!doctype html><html lang="th"><head><meta charset="utf-8"><meta name="robots" content="noindex,nofollow"><title><?=e($title)?></title><style>body{font:15px/1.8 Tahoma,sans-serif;color:#303642;max-width:850px;margin:35px auto;padding:20px}table{width:100%;border-collapse:collapse}td,th{padding:10px;border-bottom:1px solid #ddd;text-align:left}.right{text-align:right}.note{font-size:12px;color:#666}@media print{button,a.print-hide{display:none}body{margin:0;max-width:none}}</style></head><body><button onclick="window.print()"><?=e(t('พิมพ์ / บันทึก PDF'))?></button><h1><?=e($title)?></h1><p><?=e(t('เลขที่'))?> <?=e($document['number']??('BP-'.sprintf('%06d',$order['id'])))?> · <?=e($document['issued_at']??$order['created_at'])?></p><h2><?=e(($tax['legal_name']??'')?:'Baby Products')?></h2><?php if(!empty($tax['registered'])): ?><p><?=e(t('เลขผู้เสียภาษี'))?> <?=e($tax['tax_id'])?> · <?=e($tax['branch'])?><br><?=nl2br(e($tax['legal_address']))?></p><?php endif ?><h3><?=e(t('ผู้ซื้อ / ผู้รับ'))?></h3><p><?=e($buyer['name']??$order['recipient'])?><br><?=nl2br(e($buyer['address']??($order['address'].' '.$order['subdistrict'].' '.$order['district'].' '.$order['province'].' '.$order['postcode'])))?><?php if(!empty($buyer['tax_id'])): ?><br><?=e(t('เลขผู้เสียภาษี'))?> <?=e($buyer['tax_id'])?> · <?=e($buyer['branch']??'')?><?php endif ?></p><table><tr><th><?=e(t('สินค้า'))?></th><th><?=e(t('จำนวน'))?></th><th class="right"><?=e(t('ยอดหลังส่วนลด'))?></th></tr><?php foreach($items as $item): ?><tr><td><?=e(localized_name($item))?> <?=e(($item['variant_color']??'').' '.($item['variant_size']??''))?></td><td><?=$item['quantity']?></td><td class="right"><?=money($item['line_total']??(cents($item['price'])*$item['quantity']/100))?></td></tr><?php endforeach ?></table><p class="right"><?=e(t('ค่าจัดส่งสุทธิ'))?> <?=money($order['shipping'])?> <?=e(t('· ค่าบริการ COD'))?> <?=money($order['cod_fee']??0)?></p><?php if(!empty($tax['registered'])): ?><p class="right"><?=e(t('มูลค่าก่อนภาษี'))?> <?=money($order['net_before_tax'])?><br>VAT <?=number_format($tax['rate_bps']/100,2)?>% <?=money($order['vat_amount'])?></p><?php endif ?><h2 class="right"><?=e(t('ยอดสุทธิ'))?> <?=money($order['total'])?></h2><p><?=payment_method_label($order)?> · <?=e(PAYMENT_STATUSES[$order['payment_status']])?></p><?php if($kind==='summary'): ?><p class="note"><?=e(t('เอกสารสรุปนี้ไม่ใช่หลักฐานรับเงินหรือใบกำกับภาษี'))?></p><?php else: ?><p class="note"><?=e(t('เอกสารที่ร้านออกจากข้อมูลที่ผู้ดูแลยืนยัน ไม่ใช่ระบบ e-Tax Invoice ที่รับรองโดยกรมสรรพากร หากยกเลิกหรือคืนเงินภายหลัง ให้ร้านดำเนินเอกสารปรับปรุงที่เกี่ยวข้องตามกฎหมาย'))?></p><?php endif ?></body></html>
